<script setup lang="ts">
import { computed, ref, watch } from 'vue';import { useRoute } from 'vue-router';import { ElMessage, ElMessageBox } from 'element-plus';import { api, canWrite, isSuper, date, labels, session } from '../api';
const route=useRoute();const entity=computed(()=>String(route.params.entity));
const definitions: Record<string,{title:string;note:string;columns:[string,string][];states?:string[]}>={
  moderation:{title:'内容审核',note:'核查自动检测结果及待复核内容，按实际证据作出判断。',columns:[['targetType','内容类型'],['targetId','对象编号'],['state','审核状态'],['createdAt','提交时间']],states:['pending','resolved']},
  reports:{title:'举报与申诉',note:'核查用户反馈，关联证据与治理措施。',columns:[['targetType','举报对象'],['targetId','对象编号'],['kind','记录类型'],['reason','原因'],['state','处理状态'],['createdAt','提交时间']],states:['pending','resolved']},
  goods:{title:'商品治理',note:'管理商品可见性，违规下架及恢复均保留原交易记录。',columns:[['title','商品标题'],['cat','类目'],['price','价格'],['status','交易状态'],['moderationStatus','审核状态'],['enforcement','治理状态'],['createdAt','发布时间']]},
  users:{title:'用户治理',note:'按具体风险采取警告、能力限制或账号封禁。',columns:[['nickName','昵称'],['campus','校区'],['college','学院'],['accountStatus','账号状态'],['restrictedUntil','限制到期'],['restrictions','权限限制'],['createdAt','注册时间']]},
  risks:{title:'交易风控',note:'查看命中规则，核查异常低价、频繁操作与骚扰行为。',columns:[['type','风险类型'],['targetId','关联对象'],['action','风险动作'],['state','处置状态'],['createdAt','发生时间']],states:['pending','resolved']},
  audit:{title:'审计日志',note:'查询和关键操作均留痕。审计记录只读，不提供修改与删除。',columns:[['sequence','序号'],['actorId','操作者'],['action','操作'],['targetId','对象编号'],['reason','原因'],['createdAt','操作时间']]},
  admins:{title:'管理员',note:'账号独立授权，至少保留一个有效超级管理员。',columns:[['username','账号'],['role','角色'],['active','启用'],['createdAt','创建时间']]},
  tasks:{title:'后台任务',note:'任务自动重试，连续失败后可核查原因并手动重试。',columns:[['kind','任务类型'],['state','状态'],['attempts','失败次数'],['lastError','最近错误'],['createdAt','创建时间']],states:['pending','running','failed','done']}
};
const def=computed(()=>definitions[entity.value]);const list=ref<any[]>([]);const total=ref(0);const page=ref(1);const keyword=ref('');const state=ref('');const range=ref<[Date,Date] | null>(null);const loading=ref(false);const error=ref('');
const drawer=ref(false);const detail=ref<any>(null);const detailBusy=ref(false);const editing=ref(false);const edit=ref<any>({});const editBusy=ref(false);
const capabilityNames:Record<string,string>={publish:'商品管理',offer:'报价',message:'消息',upload:'上传',profile:'资料编辑'};
function format(key:string,value:any){if (key.endsWith('At') || key === 'restrictedUntil') return value ? date(value) : '—'; if (Array.isArray(value)) return value.map(x=>capabilityNames[x] || x).join('、') || '—';if(typeof value==='boolean')return value?'是':'否';return labels[String(value)]?? value ?? '—';}
async function load(){if(!def.value)return;loading.value=true;error.value='';try{const q=new URLSearchParams({entity:entity.value,page:String(page.value),keyword:keyword.value});if(state.value)q.set('state',state.value);if(range.value){q.set('from',String(+range.value[0]));q.set('to',String(+range.value[1]));}const r=await api('/list?'+q);list.value=r.list;total.value=r.total;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
watch(entity,()=>{page.value=1;keyword.value='';state.value='';drawer.value=false;load();},{immediate:true});
async function view(row:any){drawer.value=true;detail.value=null;detailBusy.value=true;try{if(['audit','tasks','admins'].includes(entity.value))detail.value={record:row};else detail.value=await api('/evidence?'+new URLSearchParams({entity:entity.value,id:row._id,reason:'核查当前治理案件的必要证据'}));}catch(e){drawer.value=false;ElMessage.error((e as Error).message);}finally{detailBusy.value=false;}}
function openEdit(op:string,row:any={}){editing.value=true;edit.value={op,id:row._id,targetId:row._id,targetType:entity.value==='goods'?'goods':'users',action:entity.value==='goods'?'remove':'warn',reason:'',confirm:false,role:row.role||'reviewer',active:row.active ?? true,hours:24,restrictions:['publish','offer','message'],username:'',password:'',...op==='moderation.decide'?{decision:'approved'}:{}};}
function caseGovern(){const r=detail.value.record;editing.value=true;edit.value={op:'govern',targetType:r.targetType==='goods'?'goods':'users',targetId:r.targetType==='goods'?r.targetId:detail.value.ownerUserId,caseId:entity.value==='reports'?r._id:undefined,action:r.targetType==='goods'?(r.kind==='appeal'?'restore':'remove'):r.kind==='appeal'?'unrestrict':'warn',reason:'',confirm:false,hours:24,restrictions:['publish','offer','message']};}
async function execute(){if(!edit.value.reason.trim()||!edit.value.confirm)return ElMessage.warning('请填写处理原因并勾选确认');editBusy.value=true;try{await api('/action',edit.value);editing.value=false;drawer.value=false;ElMessage.success('操作已提交，业务限制立即生效，关联任务自动处理');await load();}catch(e){ElMessage.error((e as Error).message);}finally{editBusy.value=false;}}
const images=computed(()=>[...(detail.value?.target?.images||[]),...(detail.value?.target?.innerPhotos||[]),...(detail.value?.target?.avatarUrl?[detail.value.target.avatarUrl]:[])]);
const detailLabels:Record<string,string>={title:'商品标题',desc:'商品说明',cat:'类目',condition:'成色',tradeType:'交易方式',price:'金额',priceSnapshot:'标价快照',campus:'校区',college:'学院',major:'专业',course:'课程',meetingPlace:'面交地点',meetingTime:'面交时间',status:'交易状态',moderationStatus:'审核状态',enforcement:'治理状态',createdAt:'创建时间',updatedAt:'更新时间',nickName:'昵称',previousNickName:'原昵称',governanceReason:'处置原因',restrictions:'权限限制',restrictedUntil:'限制到期',accountStatus:'账号状态',contact:'联系方式（脱敏）',message:'报价留言',content:'消息内容',isbn:'ISBN',author:'作者',publisher:'出版社',edition:'版次',noteLevel:'笔记等级',noteDesc:'笔记说明',defects:'缺损说明',attributes:'类目扩展信息',facts:'风险依据',type:'风险类型'};
const detailPairs=computed(()=>Object.entries(detail.value?.target||{}).filter(([k])=>Object.hasOwn(detailLabels,k)));
</script>
<template><div v-if="def"><div class="page-intro"><div><span class="eyebrow">GOVERNANCE</span><h1>{{ def.title }}</h1><p>{{ def.note }}</p></div><el-button v-if="entity==='admins'&&isSuper()" type="primary" @click="openEdit('admin.create')">新建管理员</el-button></div><section class="panel"><div class="filter-bar"><el-input v-model="keyword" clearable placeholder="搜索关键词或对象编号" style="width:250px" @keyup.enter="page=1;load()"/><el-select v-if="def.states" v-model="state" clearable placeholder="全部状态" style="width:150px"><el-option v-for="v in def.states" :key="v" :value="v" :label="labels[v]||v"/></el-select><el-date-picker v-model="range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" style="max-width:360px"/><el-button type="primary" @click="page=1;load()">查询</el-button><el-button @click="keyword='';state='';range=null;page=1;load()">重置</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-table v-loading="loading" :data="list" stripe empty-text="暂无符合条件的记录" row-key="_id"><el-table-column v-for="[key,label] in def.columns" :key="key" :label="label" :min-width="key.endsWith('At')?170:140" show-overflow-tooltip><template #default="{row}"><el-tag v-if="['state','status','moderationStatus','enforcement','accountStatus','role'].includes(key)" :type="['failed','banned','removed','rejected'].includes(row[key])?'danger':['pending','review','restricted'].includes(row[key])?'warning':'info'" effect="light">{{ format(key,row[key]) }}</el-tag><span v-else>{{ format(key,row[key]) }}</span></template></el-table-column><el-table-column label="操作" fixed="right" :width="entity==='users'||entity==='goods'?180:140"><template #default="{row}"><el-button v-if="canWrite()||entity==='tasks'" link type="primary" @click="view(row)">详情</el-button><el-button v-if="canWrite()&&['goods','users'].includes(entity)&&row.accountStatus!=='deleted'&&row.status!=='deleted'" link type="primary" @click="openEdit('govern',row)">处置</el-button><el-button v-if="canWrite() && ['goods','users'].includes(entity) && !row.moderationStatus" link @click="openEdit('moderation.queue',row)">送审</el-button><el-button v-if="entity==='admins'&&isSuper()" link type="primary" @click="openEdit('admin.update',row)">管理</el-button><el-button v-if="entity==='tasks'&&row.state==='failed'&&canWrite()" link type="primary" @click="openEdit('task.retry',row)">重试</el-button><span v-if="!canWrite()&&entity!=='tasks'" class="muted">只读</span></template></el-table-column></el-table><div class="pagination"><span class="muted">共 {{ total }} 条记录</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next" @current-change="load"/></div></section>
<el-drawer v-model="drawer" title="记录与必要证据" size="min(700px, 95vw)"><div v-loading="detailBusy" style="min-height:200px"><template v-if="detail"><div class="detail-id">{{ detail.record._id }}</div><el-alert v-if="detail.detection" :title="'检测状态：'+(labels[detail.detection.status]||detail.detection.status)+'；'+detail.detection.reason" :closable="false" type="info" class="mb"/><p v-if="detail.reportDetail" class="prewrap">举报说明 {{ detail.reportDetail }}</p><el-descriptions :column="1" border><el-descriptions-item v-for="[k,v] in detailPairs" :key="k" :label="detailLabels[k]||k"><span class="prewrap">{{ typeof v==='object'?JSON.stringify(v,null,2):format(k,v) }}</span></el-descriptions-item></el-descriptions><el-image v-for="img in images" :key="img" :src="img" :preview-src-list="images" class="evidence-image" fit="cover"/><div v-if="['audit','tasks','admins'].includes(entity)" class="json-view">{{ JSON.stringify(detail.record,null,2) }}</div><div class="drawer-actions" v-if="canWrite()"><el-button v-if="entity==='moderation'" @click="openEdit('moderation.reopen',detail.record)">重新人工复核</el-button><template v-if="entity==='moderation'&&detail.record.state==='pending'"><el-button type="primary" @click="openEdit('moderation.decide',detail.record)">审核决定</el-button></template><template v-if="entity==='reports'&&detail.record.state==='pending'"><el-button type="primary" @click="caseGovern">采取处置</el-button><el-button @click="openEdit('report.dismiss',detail.record)">核查不成立</el-button></template><el-button v-if="entity==='risks'&&detail.ownerUserId" @click="caseGovern">处置关联用户</el-button><el-button v-if="entity==='risks'&&detail.record.state==='pending'" type="primary" @click="openEdit('risk.resolve',detail.record)">记录核查结果</el-button></div></template></div></el-drawer>
<el-dialog v-model="editing" title="确认管理操作" width="530px" destroy-on-close><el-form label-position="top"><template v-if="edit.op==='admin.create'"><el-form-item label="账号（3至40位字母、数字或 _.-）"><el-input v-model="edit.username"/></el-form-item><el-form-item label="初始密码（至少12位）"><el-input v-model="edit.password" type="password" show-password autocomplete="new-password"/></el-form-item></template><template v-if="['admin.create','admin.update'].includes(edit.op)"><el-form-item label="角色"><el-select v-model="edit.role"><el-option value="super" label="超级管理员"/><el-option value="reviewer" label="审核员"/><el-option value="readonly" label="运营只读"/></el-select></el-form-item><el-form-item v-if="edit.op==='admin.update'" label="启用状态"><el-switch v-model="edit.active"/></el-form-item></template><el-form-item v-if="edit.op==='moderation.decide'" label="审核结果"><el-radio-group v-model="edit.decision"><el-radio value="approved">通过</el-radio><el-radio value="rejected">驳回</el-radio></el-radio-group></el-form-item><template v-if="edit.op==='govern'"><el-form-item label="处置措施"><el-select v-model="edit.action"><template v-if="edit.targetType==='goods'"><el-option value="remove" label="违规下架"/><el-option value="restore" label="恢复（须审核通过）"/></template><template v-else><el-option value="warn" label="警告"/><el-option value="restrict" label="限制能力"/><el-option value="ban" label="封禁账号"/><el-option value="unrestrict" label="解除限制或封禁"/></template></el-select></el-form-item><template v-if="edit.action==='restrict'"><el-form-item label="限制能力"><el-checkbox-group v-model="edit.restrictions"><el-checkbox value="publish">发布</el-checkbox><el-checkbox value="offer">报价</el-checkbox><el-checkbox value="message">消息</el-checkbox><el-checkbox value="upload">上传</el-checkbox><el-checkbox value="profile">编辑资料</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="限制小时数"><el-input-number v-model="edit.hours" :min="1" :max="8760"/></el-form-item></template></template><el-form-item label="具体原因 / 核查结论（必填）"><el-input v-model="edit.reason" type="textarea" :rows="4" maxlength="500" show-word-limit/></el-form-item><el-alert title="操作将记录审计。治理处置可能影响相关商品、申请与会话，并通知相关用户。" type="warning" :closable="false"/><el-checkbox v-model="edit.confirm" class="mt">我已核对对象、措施和影响范围，确认执行</el-checkbox></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="editBusy" @click="execute">确认执行</el-button></template></el-dialog></div><el-empty v-else description="页面不存在"/></template>
